function validate([s1, s2, x]) {
  if (typeof s1 !== 'string' || typeof s2 !== 'string') return 's1 and s2 must be strings.';
  if (s1.length !== s2.length) return 's1 and s2 must have the same length.';
  if (s1.length < 1 || s1.length > 500) return 'The strings need 1 to 500 characters.';
  if (!/^[01]+$/.test(s1) || !/^[01]+$/.test(s2)) return 'The strings may contain only 0 and 1.';
  if (!Number.isInteger(x) || x < 1 || x > 500) return 'x is an integer between 1 and 500.';
  return null;
}

