function minOperations(s1, s2, x) {
  const diff = [];
  for (let i = 0; i < s1.length; i++) {
    if (s1[i] !== s2[i]) {
      diff.push(i);
    }
  }
  const m = diff.length;
  if (m % 2 === 1) {
    return -1;
  }
  // dp[k] is twice the cheapest cost of fixing the first k mismatches.
  const dp = new Array(m + 1).fill(0);
  for (let k = 1; k <= m; k++) {
    dp[k] = dp[k - 1] + x;
    if (k >= 2) {
      const walk = 2 * (diff[k - 1] - diff[k - 2]);
      dp[k] = Math.min(dp[k], dp[k - 2] + walk);
    }
  }
  return dp[m] / 2;
}

