function minOperations(s1, s2, x) {
  // Dijkstra over every possible mismatch mask.
  const n = s1.length;
  let start = 0;
  for (let i = 0; i < n; i++) if (s1[i] !== s2[i]) start |= 1 << i;
  const size = 1 << n;
  const dist = new Array(size).fill(Infinity);
  const done = new Array(size).fill(false);
  dist[start] = 0;
  for (;;) {
    let u = -1;
    for (let v = 0; v < size; v++) if (!done[v] && dist[v] < Infinity && (u === -1 || dist[v] < dist[u])) u = v;
    if (u === -1) break;
    if (u === 0) return dist[0];
    done[u] = true;
    for (let i = 0; i < n; i++)
      for (let j = i + 1; j < n; j++) {
        const cost = j === i + 1 ? Math.min(1, x) : x;
        const v = u ^ (1 << i) ^ (1 << j);
        if (dist[u] + cost < dist[v]) dist[v] = dist[u] + cost;
      }
  }
  return -1;
}

