function generate(rand, size) {
  const n = size === 'large' ? 300 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 9);
  const x = size === 'large' ? 1 + Math.floor(rand() * 500) : 1 + Math.floor(rand() * 8);
  const density = rand();
  let s1 = '';
  let s2 = '';
  for (let i = 0; i < n; i++) {
    const a = rand() < 0.5 ? '0' : '1';
    s1 += a;
    s2 += rand() < density ? (a === '0' ? '1' : '0') : a;
  }
  // Usually keep the number of mismatches even so most cases have an answer.
  if (rand() < 0.8) {
    let count = 0;
    for (let i = 0; i < n; i++) if (s1[i] !== s2[i]) count++;
    if (count % 2 === 1) {
      const i = Math.floor(rand() * n);
      s2 = s2.slice(0, i) + (s2[i] === '0' ? '1' : '0') + s2.slice(i + 1);
    }
  }
  return [s1, s2, x];
}
